    const auto unknown_b_before = unknown_b_machine.execution().cpu().state();
    const auto unknown_b = unknown_b_machine.execution().step_instruction();
    passed &= expect(
        unknown_b.fault == CpuFault::unknown_state
            && unknown_b.state_fault == CpuStatePart::accumulator_b
            && unknown_b.bytes_fetched == 1U
            && unknown_b.instruction_length == 1U && unknown_b.cycles == 0U
            && unknown_b_machine.execution().cpu().state() == unknown_b_before,
        "TBA consumed unresolved reset-time accumulator B"
    );

    RamBus wrap_bus;
    RecordingObserver wrap_observer;
    constexpr std::array<std::uint8_t, 3U> wrap_program{
        0xC6U, 0x5AU, 0x17U,
    };
    passed &= expect(
        wrap_bus.load(0xFFFDU, wrap_program)
            && wrap_bus.set_observer(&wrap_observer),
        "TBA PC-wrap setup failed"
    );
    Cpu wrap_cpu;
    wrap_cpu.initialize(CpuProfile::hd6301v1, 0xFFFDU, 0x01FFU);
    passed &= expect(
        wrap_cpu.step_instruction(wrap_bus).succeeded(),
        "TBA PC-wrap accumulator seed failed"
    );
    wrap_observer.clear();
    const auto wrap_step = wrap_cpu.step_instruction(wrap_bus);
    passed &= expect(
        wrap_step.succeeded() && wrap_step.pc_before == 0xFFFFU
            && wrap_step.pc_after == 0x0000U && wrap_step.cycles == 1U
            && wrap_cpu.state().a == 0x5AU && wrap_cpu.state().b == 0x5AU
            && wrap_observer.count == 1U
            && wrap_observer.events[0].address == 0xFFFFU
            && wrap_observer.events[0].value == 0x17U,
        "TBA did not wrap the 16-bit program counter"
    );

    RamBus mc6801_bus;
    mc6801_bus.poke8(0x1000U, 0x17U);
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
