bool test_lsra() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::CpuRegister;
    using jr800::core::CpuStatePart;
    using jr800::core::Jr800Machine;
    using jr800::core::Jr800MemoryStatus;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    constexpr auto negative = condition_mask(ConditionCode::negative);
    constexpr auto zero = condition_mask(ConditionCode::zero);
    constexpr auto overflow = condition_mask(ConditionCode::overflow);
    constexpr auto carry = condition_mask(ConditionCode::carry);
    constexpr auto written = static_cast<std::uint8_t>(
        negative | zero | overflow | carry
    );

    RamBus exhaustive_bus;
    Cpu exhaustive_cpu;
    RecordingObserver observer;
    bool passed = expect(
        exhaustive_bus.set_observer(&observer),
        "LSRA observer attach failed"
    );
    bool exhaustive_match = true;
    for (std::uint16_t input = 0U;
         input <= 0x00FFU && exhaustive_match;
         ++input) {
        const auto operand = static_cast<std::uint8_t>(input);
        const std::array<std::uint8_t, 3U> program{
            0x86U,
            operand,
            0x44U,
        };
        exhaustive_match = exhaustive_bus.load(0x1000U, program);
        exhaustive_cpu.initialize(
            CpuProfile::hd6301v1,
            0x1000U,
            0x01FFU
        );
        if (!exhaustive_match
            || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()) {
            exhaustive_match = false;
            break;
        }

        const auto before = exhaustive_cpu.state();
        observer.clear();
        const auto result = static_cast<std::uint8_t>(operand >> 1U);
        const auto carry_set = (operand & 0x01U) != 0U;
        auto expected = before;
        expected.a = result;
        expected.condition_code = static_cast<std::uint8_t>(
            expected.condition_code & ~written
        );
        if (result == 0U) {
            expected.condition_code = static_cast<std::uint8_t>(
                expected.condition_code | zero
            );
        }
        if (carry_set) {
            expected.condition_code = static_cast<std::uint8_t>(
                expected.condition_code | overflow | carry
            );
        }
        expected.knowledge.condition_code = static_cast<std::uint8_t>(
            expected.knowledge.condition_code | written
        );
        expected.pc = 0x1003U;
        expected.cycle_count = 3U;

        const auto step = exhaustive_cpu.step_instruction(exhaustive_bus);
        exhaustive_match = before.a == operand
            && step.succeeded() && step.bytes_fetched == 1U
            && step.instruction_length == 1U && step.cycles == 1U
            && step.pc_before == 0x1002U && step.pc_after == 0x1003U
            && step.bytes[0] == 0x44U
            && exhaustive_cpu.state() == expected
            && observer.count == 1U
            && observer.events[0].kind == AccessKind::instruction_fetch
            && observer.events[0].address == 0x1002U
            && observer.events[0].value == 0x44U;
    }
    passed &= expect(
        exhaustive_match,
        "LSRA exhaustive result, flags, state, timing, or trace differs"
    );

    RamBus overwrite_bus;
    constexpr std::array<std::uint8_t, 8U> overwrite_program{
        0x86U, 0x00U,
        0xC6U, 0x7FU,
        0xC1U, 0xFFU,
        0x0FU,
        0x44U,
    };
    passed &= expect(
        overwrite_bus.load(0x1000U, overwrite_program),
        "LSRA overwrite program load failed"
    );
    Cpu overwrite_cpu;
    overwrite_cpu.initialize(CpuProfile::hd6301v1, 0x1000U, 0x01FFU);
    passed &= expect(
        overwrite_cpu.step_instruction(overwrite_bus).succeeded()
            && overwrite_cpu.step_instruction(overwrite_bus).succeeded()
            && overwrite_cpu.step_instruction(overwrite_bus).succeeded()
            && overwrite_cpu.step_instruction(overwrite_bus).succeeded(),
        "LSRA overwrite state seed failed"
    );
    const auto overwrite_before = overwrite_cpu.state();
    auto overwrite_expected = overwrite_before;
    overwrite_expected.condition_code = static_cast<std::uint8_t>(
        (overwrite_expected.condition_code & ~written) | zero
    );
    overwrite_expected.knowledge.condition_code = static_cast<std::uint8_t>(
        overwrite_expected.knowledge.condition_code | written
    );
    overwrite_expected.pc = 0x1008U;
    overwrite_expected.cycle_count = 8U;
    constexpr auto preexisting = static_cast<std::uint8_t>(
        negative | overflow | carry
    );
    const auto overwrite_step = overwrite_cpu.step_instruction(overwrite_bus);
    passed &= expect(
        (overwrite_before.condition_code & preexisting) == preexisting
            && overwrite_step.succeeded()
            && overwrite_cpu.state() == overwrite_expected,
        "LSRA did not overwrite N/Z/V/C while preserving H/I and B"
    );

    Jr800Machine partial_machine;
    auto partial_rom = nop_rom();
    partial_rom[0U] = 0x86U;
    partial_rom[1U] = 0x01U;
    partial_rom[2U] = 0x44U;
    partial_rom[partial_rom.size() - 2U] = 0x80U;
    partial_rom[partial_rom.size() - 1U] = 0x00U;
    passed &= expect(
        partial_machine.load_logical_rom(partial_rom) == Jr800MemoryStatus::ok
            && partial_machine.initialize_from_reset_entry().succeeded()
            && partial_machine.execution().step_instruction().succeeded(),
        "LSRA partial-knownness setup failed"
    );
    const auto partial_before = partial_machine.execution().cpu().state();
    auto partial_expected = partial_before;
    partial_expected.a = 0x00U;
    partial_expected.condition_code = static_cast<std::uint8_t>(
        (partial_expected.condition_code & ~written)
        | zero
        | overflow
        | carry
    );
    partial_expected.knowledge.condition_code = static_cast<std::uint8_t>(
        partial_expected.knowledge.condition_code | written
    );
    partial_expected.pc = 0x8003U;
    partial_expected.cycle_count = 3U;
    const auto partial_step = partial_machine.execution().step_instruction();
    passed &= expect(
        !partial_before.knowledge.knows(CpuRegister::accumulator_b)
            && partial_before.knowledge.knows(CpuRegister::accumulator_a)
            && partial_step.succeeded() && partial_step.bytes_fetched == 1U
            && partial_step.cycles == 1U
            && partial_machine.execution().cpu().state() == partial_expected,
        "LSRA changed unrelated reset-time values or knownness"
    );

    RamBus wrap_bus;
    RecordingObserver wrap_observer;
    passed &= expect(
        wrap_bus.set_observer(&wrap_observer),
        "LSRA wrap observer attach failed"
    );
    constexpr std::array<std::uint8_t, 3U> wrap_program{
        0x86U, 0x01U, 0x44U,
    };
    passed &= expect(
        wrap_bus.load(0xFFFDU, wrap_program),
        "LSRA wrap program load failed"
    );
    Cpu wrap_cpu;
    wrap_cpu.initialize(CpuProfile::hd6301v1, 0xFFFDU, 0x01FFU);
    passed &= expect(
        wrap_cpu.step_instruction(wrap_bus).succeeded(),
        "LSRA wrap state seed failed"
    );
    const auto wrap_before = wrap_cpu.state();
    auto wrap_expected = wrap_before;
    wrap_expected.a = 0x00U;
    wrap_expected.condition_code = static_cast<std::uint8_t>(
        (wrap_expected.condition_code & ~written)
        | zero
        | overflow
        | carry
    );
    wrap_expected.knowledge.condition_code = static_cast<std::uint8_t>(
        wrap_expected.knowledge.condition_code | written
    );
    wrap_expected.pc = 0x0000U;
    wrap_expected.cycle_count = 3U;
    wrap_observer.clear();
    const auto wrap_step = wrap_cpu.step_instruction(wrap_bus);
    passed &= expect(
        wrap_step.succeeded() && wrap_step.pc_before == 0xFFFFU
            && wrap_step.pc_after == 0x0000U && wrap_step.cycles == 1U
            && wrap_cpu.state() == wrap_expected
            && wrap_observer.count == 1U
            && wrap_observer.events[0].kind == AccessKind::instruction_fetch
            && wrap_observer.events[0].address == 0xFFFFU
            && wrap_observer.events[0].value == 0x44U,
        "LSRA PC wrap, state, or architectural fetch differs"
    );

    Jr800Machine unknown_a_machine;
    auto unknown_a_rom = nop_rom();
    unknown_a_rom[0U] = 0x44U;
    unknown_a_rom[unknown_a_rom.size() - 2U] = 0x80U;
    unknown_a_rom[unknown_a_rom.size() - 1U] = 0x00U;
    passed &= expect(
        unknown_a_machine.load_logical_rom(unknown_a_rom)
                == Jr800MemoryStatus::ok
            && unknown_a_machine.initialize_from_reset_entry().succeeded(),
        "LSRA unknown-A setup failed"
    );
    const auto unknown_before = unknown_a_machine.execution().cpu().state();
    const auto unknown = unknown_a_machine.execution().step_instruction();
    passed &= expect(
        unknown.fault == CpuFault::unknown_state
            && unknown.state_fault == CpuStatePart::accumulator_a
            && unknown.bytes_fetched == 1U
            && unknown.instruction_length == 1U && unknown.cycles == 0U
            && unknown_a_machine.execution().cpu().state() == unknown_before,
        "LSRA consumed unresolved reset-time accumulator A"
    );

    RamBus mc6801_bus;
    constexpr std::array<std::uint8_t, 1U> unstaged_program{0x44U};
    passed &= expect(
        mc6801_bus.load(0x1000U, unstaged_program),
        "MC6801 LSRA profile test load failed"
    );
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 LSRA execution was inherited"
    );
    return passed;
}

bool test_lsrb() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::CpuRegister;
    using jr800::core::CpuStatePart;
    using jr800::core::Jr800Machine;
    using jr800::core::Jr800MemoryStatus;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    constexpr auto negative = condition_mask(ConditionCode::negative);
    constexpr auto zero = condition_mask(ConditionCode::zero);
    constexpr auto overflow = condition_mask(ConditionCode::overflow);
    constexpr auto carry = condition_mask(ConditionCode::carry);
    constexpr auto written = static_cast<std::uint8_t>(
        negative | zero | overflow | carry
    );

    bool passed = true;
    for (std::uint16_t input = 0U; input <= 0x00FFU; ++input) {
        const auto operand = static_cast<std::uint8_t>(input);
        RamBus bus;
        RecordingObserver observer;
        passed &= expect(bus.set_observer(&observer), "LSRB observer attach failed");
        const std::array<std::uint8_t, 3U> program{
            0xC6U,
            operand,
            0x54U,
        };
        passed &= expect(bus.load(0x1000U, program), "LSRB program load failed");

        Cpu cpu;
        cpu.initialize(CpuProfile::hd6301v1, 0x1000U, 0x01FFU);
        passed &= expect(
            cpu.step_instruction(bus).succeeded(),
            "LSRB accumulator seed failed"
        );
        const auto before = cpu.state();
        observer.clear();

        const auto result = static_cast<std::uint8_t>(operand >> 1U);
        const auto carry_set = (operand & 0x01U) != 0U;
        const auto negative_set = (result & 0x80U) != 0U;
        auto expected = before;
        expected.b = result;
        expected.condition_code = static_cast<std::uint8_t>(
            expected.condition_code & ~written
        );
        if (negative_set) {
            expected.condition_code = static_cast<std::uint8_t>(
                expected.condition_code | negative
            );
        }
        if (result == 0U) {
            expected.condition_code = static_cast<std::uint8_t>(
                expected.condition_code | zero
            );
        }
        if (negative_set != carry_set) {
            expected.condition_code = static_cast<std::uint8_t>(
                expected.condition_code | overflow
            );
        }
        if (carry_set) {
            expected.condition_code = static_cast<std::uint8_t>(
                expected.condition_code | carry
            );
        }
        expected.knowledge.condition_code = static_cast<std::uint8_t>(
            expected.knowledge.condition_code | written
        );
        expected.pc = 0x1003U;
        expected.cycle_count = 3U;

        const auto step = cpu.step_instruction(bus);
        passed &= expect(
            step.succeeded() && step.bytes_fetched == 1U
                && step.instruction_length == 1U && step.cycles == 1U
                && step.pc_before == 0x1002U && step.pc_after == 0x1003U
                && step.bytes[0] == 0x54U && cpu.state() == expected,
            "LSRB exhaustive result, flags, knownness, or timing differs"
        );
        passed &= expect(
            observer.count == 1U
                && observer.events[0].kind == AccessKind::instruction_fetch
                && observer.events[0].address == 0x1002U
                && observer.events[0].value == 0x54U,
            "LSRB architectural fetch order differs"
        );
    }

    RamBus overwrite_bus;
    constexpr std::array<std::uint8_t, 8U> overwrite_program{
        0xC6U, 0x00U,
        0x86U, 0x7FU,
        0x81U, 0xFFU,
        0x0FU,
        0x54U,
    };
    passed &= expect(
        overwrite_bus.load(0x1000U, overwrite_program),
        "LSRB overwrite program load failed"
    );
    Cpu overwrite_cpu;
    overwrite_cpu.initialize(CpuProfile::hd6301v1, 0x1000U, 0x01FFU);
    passed &= expect(
        overwrite_cpu.step_instruction(overwrite_bus).succeeded()
            && overwrite_cpu.step_instruction(overwrite_bus).succeeded()
            && overwrite_cpu.step_instruction(overwrite_bus).succeeded()
            && overwrite_cpu.step_instruction(overwrite_bus).succeeded(),
        "LSRB overwrite state seed failed"
    );
    const auto overwrite_before = overwrite_cpu.state();
    auto overwrite_expected = overwrite_before;
    overwrite_expected.condition_code = static_cast<std::uint8_t>(
        (overwrite_expected.condition_code & ~written) | zero
    );
    overwrite_expected.pc = 0x1008U;
    overwrite_expected.cycle_count = 8U;
    constexpr auto preexisting = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::interrupt_mask)
        | negative
        | overflow
        | carry
    );
    const auto overwrite_step = overwrite_cpu.step_instruction(overwrite_bus);
    passed &= expect(
        (overwrite_before.condition_code & preexisting) == preexisting
            && overwrite_step.succeeded()
            && overwrite_cpu.state() == overwrite_expected,
        "LSRB did not overwrite N/Z/V/C while preserving H/I"
    );

    Jr800Machine partial_knowledge_machine;
    auto partial_knowledge_rom = nop_rom();
    partial_knowledge_rom[0U] = 0xC6U;
    partial_knowledge_rom[1U] = 0x01U;
    partial_knowledge_rom[2U] = 0x54U;
    partial_knowledge_rom[partial_knowledge_rom.size() - 2U] = 0x80U;
    partial_knowledge_rom[partial_knowledge_rom.size() - 1U] = 0x00U;
    passed &= expect(
        partial_knowledge_machine.load_logical_rom(partial_knowledge_rom)
                == Jr800MemoryStatus::ok
            && partial_knowledge_machine.initialize_from_reset_entry().succeeded()
            && partial_knowledge_machine.execution().step_instruction().succeeded(),
        "LSRB partial-knownness setup failed"
    );
    const auto partial_before =
        partial_knowledge_machine.execution().cpu().state();
    auto partial_expected = partial_before;
    partial_expected.b = 0x00U;
    partial_expected.condition_code = static_cast<std::uint8_t>(
        (partial_expected.condition_code & ~written)
        | zero
        | overflow
        | carry
    );
    partial_expected.knowledge.condition_code = static_cast<std::uint8_t>(
        partial_expected.knowledge.condition_code | written
    );
    partial_expected.pc = 0x8003U;
    partial_expected.cycle_count = 3U;
    const auto partial_step =
        partial_knowledge_machine.execution().step_instruction();
    const auto half_carry = condition_mask(ConditionCode::half_carry);
    passed &= expect(
        !partial_before.knowledge.knows(CpuRegister::accumulator_a)
            && (partial_before.knowledge.condition_code & half_carry) == 0U
            && partial_step.succeeded() && partial_step.cycles == 1U
            && partial_knowledge_machine.execution().cpu().state()
                == partial_expected,
        "LSRB changed unrelated reset-time values or knownness"
    );

    Jr800Machine unknown_b_machine;
    auto unknown_b_rom = nop_rom();
    unknown_b_rom[0U] = 0x54U;
    unknown_b_rom[unknown_b_rom.size() - 2U] = 0x80U;
    unknown_b_rom[unknown_b_rom.size() - 1U] = 0x00U;
    passed &= expect(
        unknown_b_machine.load_logical_rom(unknown_b_rom)
                == Jr800MemoryStatus::ok
            && unknown_b_machine.initialize_from_reset_entry().succeeded(),
        "Unknown-B LSRB setup failed"
    );
    const auto unknown_b_before = unknown_b_machine.execution().cpu().state();
    const auto unknown_b = unknown_b_machine.execution().step_instruction();
    passed &= expect(
        unknown_b.fault == CpuFault::unknown_state
            && unknown_b.state_fault == CpuStatePart::accumulator_b
            && unknown_b.bytes_fetched == 1U
            && unknown_b.instruction_length == 1U
            && unknown_b_machine.execution().cpu().state() == unknown_b_before,
        "LSRB consumed unresolved reset-time accumulator B"
    );

    RamBus mc6801_bus;
    mc6801_bus.poke8(0x1000U, 0x54U);
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 LSRB execution was inherited"
    );
    return passed;
}

bool test_rola() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::CpuRegister;
    using jr800::core::CpuStatePart;
    using jr800::core::Jr800Machine;
    using jr800::core::Jr800MemoryStatus;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    constexpr auto negative = condition_mask(ConditionCode::negative);
    constexpr auto zero = condition_mask(ConditionCode::zero);
    constexpr auto overflow = condition_mask(ConditionCode::overflow);
    constexpr auto carry = condition_mask(ConditionCode::carry);
    constexpr auto written = static_cast<std::uint8_t>(
        negative | zero | overflow | carry
    );
    constexpr auto preserved = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::half_carry)
        | condition_mask(ConditionCode::interrupt_mask)
    );

    RamBus exhaustive_bus;
    Cpu exhaustive_cpu;
    RecordingObserver observer;
    bool passed = expect(
        exhaustive_bus.set_observer(&observer),
        "ROLA observer attach failed"
    );
    bool exhaustive_match = true;
    for (std::uint16_t input = 0U;
         input <= 0x00FFU && exhaustive_match;
         ++input) {
        for (std::uint8_t carry_input = 0U;
             carry_input <= 1U && exhaustive_match;
             ++carry_input) {
            const auto operand = static_cast<std::uint8_t>(input);
            const std::array<std::uint8_t, 10U> program{
                0x86U, 0x30U,
                0x06U,
                0xC6U, 0x5AU,
                0x86U, operand,
                static_cast<std::uint8_t>(
                    carry_input != 0U ? 0x0DU : 0x0CU
                ),
                0x0BU,
                0x49U,
            };
            exhaustive_match = exhaustive_bus.load(0x1000U, program);
            exhaustive_cpu.initialize(
                CpuProfile::hd6301v1,
                0x1000U,
                0x01FFU
            );
            if (!exhaustive_match
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()) {
                exhaustive_match = false;
                break;
            }

            const auto before = exhaustive_cpu.state();
            observer.clear();
            const auto result = static_cast<std::uint8_t>(
                static_cast<std::uint8_t>(operand << 1U)
                | carry_input
            );
            const auto new_carry_set = (operand & 0x80U) != 0U;
            const auto negative_set = (result & 0x80U) != 0U;
            std::uint8_t expected_flags{};
            if (negative_set) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | negative
                );
            }
            if (result == 0U) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | zero
                );
            }
            if (negative_set != new_carry_set) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | overflow
                );
            }
            if (new_carry_set) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | carry
                );
            }
            auto expected = before;
            expected.a = result;
            expected.condition_code = static_cast<std::uint8_t>(
                (expected.condition_code & ~written) | expected_flags
            );
            expected.knowledge.condition_code = static_cast<std::uint8_t>(
                expected.knowledge.condition_code | written
            );
            expected.pc = 0x100AU;
            expected.cycle_count = 10U;

            const auto step = exhaustive_cpu.step_instruction(exhaustive_bus);
            exhaustive_match = before.a == operand && before.b == 0x5AU
                && (before.condition_code & preserved) == preserved
                && (before.condition_code & overflow) == overflow
                && ((before.condition_code & carry) != 0U)
                    == (carry_input != 0U)
                && step.succeeded() && step.bytes_fetched == 1U
                && step.instruction_length == 1U && step.cycles == 1U
                && step.pc_before == 0x1009U && step.pc_after == 0x100AU
                && step.bytes[0] == 0x49U
                && exhaustive_cpu.state() == expected
                && observer.count == 1U
                && observer.events[0].kind == AccessKind::instruction_fetch
                && observer.events[0].address == 0x1009U
                && observer.events[0].value == 0x49U;
        }
    }
    passed &= expect(
        exhaustive_match,
        "ROLA exhaustive result, carry input, flags, state, timing, or trace differs"
    );

    Jr800Machine partial_machine;
    auto partial_rom = nop_rom();
    partial_rom[0U] = 0x86U;
    partial_rom[1U] = 0x00U;
    partial_rom[2U] = 0x0DU;
    partial_rom[3U] = 0x49U;
    partial_rom[partial_rom.size() - 2U] = 0x80U;
    partial_rom[partial_rom.size() - 1U] = 0x00U;
    passed &= expect(
        partial_machine.load_logical_rom(partial_rom) == Jr800MemoryStatus::ok
            && partial_machine.initialize_from_reset_entry().succeeded()
            && partial_machine.execution().step_instruction().succeeded()
            && partial_machine.execution().step_instruction().succeeded(),
        "ROLA partial-knownness setup failed"
    );
    const auto partial_before = partial_machine.execution().cpu().state();
    auto partial_expected = partial_before;
    partial_expected.a = 0x01U;
    partial_expected.condition_code = static_cast<std::uint8_t>(
        partial_expected.condition_code & ~written
    );
    partial_expected.knowledge.condition_code = static_cast<std::uint8_t>(
        partial_expected.knowledge.condition_code | written
    );
    partial_expected.pc = 0x8004U;
    partial_expected.cycle_count = 4U;
    const auto partial_step = partial_machine.execution().step_instruction();
    passed &= expect(
        partial_before.knowledge.knows(CpuRegister::accumulator_a)
            && !partial_before.knowledge.knows(CpuRegister::accumulator_b)
            && !partial_before.knowledge.knows(CpuRegister::index_register)
            && !partial_before.knowledge.knows(CpuRegister::stack_pointer)
            && (partial_before.knowledge.condition_code & carry) == carry
            && partial_step.succeeded() && partial_step.bytes_fetched == 1U
            && partial_step.cycles == 1U
            && partial_machine.execution().cpu().state() == partial_expected,
        "ROLA changed preserved reset-time state or knownness"
    );

    RamBus wrap_bus;
    RecordingObserver wrap_observer;
    passed &= expect(
        wrap_bus.set_observer(&wrap_observer),
        "ROLA wrap observer attach failed"
    );
    constexpr std::array<std::uint8_t, 4U> wrap_program{
        0x86U, 0x80U, 0x0DU, 0x49U,
    };
    passed &= expect(
        wrap_bus.load(0xFFFCU, wrap_program),
        "ROLA wrap program load failed"
    );
    Cpu wrap_cpu;
    wrap_cpu.initialize(CpuProfile::hd6301v1, 0xFFFCU, 0x01FFU);
    passed &= expect(
        wrap_cpu.step_instruction(wrap_bus).succeeded()
            && wrap_cpu.step_instruction(wrap_bus).succeeded(),
        "ROLA wrap state seed failed"
    );
    wrap_observer.clear();
    const auto wrap_step = wrap_cpu.step_instruction(wrap_bus);
    passed &= expect(
        wrap_step.succeeded() && wrap_step.pc_before == 0xFFFFU
            && wrap_step.pc_after == 0x0000U && wrap_step.cycles == 1U
            && wrap_cpu.state().a == 0x01U
            && (wrap_cpu.state().condition_code & written)
                == static_cast<std::uint8_t>(overflow | carry)
            && wrap_observer.count == 1U
            && wrap_observer.events[0].kind == AccessKind::instruction_fetch
            && wrap_observer.events[0].address == 0xFFFFU
            && wrap_observer.events[0].value == 0x49U,
        "ROLA PC wrap, carry case, or architectural fetch differs"
    );

    Jr800Machine unknown_a_machine;
    auto unknown_a_rom = nop_rom();
    unknown_a_rom[0U] = 0x49U;
    unknown_a_rom[unknown_a_rom.size() - 2U] = 0x80U;
    unknown_a_rom[unknown_a_rom.size() - 1U] = 0x00U;
    passed &= expect(
        unknown_a_machine.load_logical_rom(unknown_a_rom)
                == Jr800MemoryStatus::ok
            && unknown_a_machine.initialize_from_reset_entry().succeeded(),
        "ROLA unknown-A setup failed"
    );
    const auto unknown_a_before = unknown_a_machine.execution().cpu().state();
    const auto unknown_a = unknown_a_machine.execution().step_instruction();
    passed &= expect(
        unknown_a.fault == CpuFault::unknown_state
            && unknown_a.state_fault == CpuStatePart::accumulator_a
            && unknown_a.bytes_fetched == 1U
            && unknown_a.instruction_length == 1U && unknown_a.cycles == 0U
            && unknown_a_machine.execution().cpu().state() == unknown_a_before,
        "ROLA did not prioritize unresolved accumulator A"
    );

    Jr800Machine unknown_c_machine;
    auto unknown_c_rom = nop_rom();
    unknown_c_rom[0U] = 0x86U;
    unknown_c_rom[1U] = 0x01U;
    unknown_c_rom[2U] = 0x49U;
    unknown_c_rom[unknown_c_rom.size() - 2U] = 0x80U;
    unknown_c_rom[unknown_c_rom.size() - 1U] = 0x00U;
    passed &= expect(
        unknown_c_machine.load_logical_rom(unknown_c_rom)
                == Jr800MemoryStatus::ok
            && unknown_c_machine.initialize_from_reset_entry().succeeded()
            && unknown_c_machine.execution().step_instruction().succeeded(),
        "ROLA unknown-C setup failed"
    );
    const auto unknown_c_before = unknown_c_machine.execution().cpu().state();
    const auto unknown_c = unknown_c_machine.execution().step_instruction();
    passed &= expect(
        unknown_c.fault == CpuFault::unknown_state
            && unknown_c.state_fault == CpuStatePart::condition_code
            && unknown_c.bytes_fetched == 1U
            && unknown_c.instruction_length == 1U && unknown_c.cycles == 0U
            && unknown_c_machine.execution().cpu().state() == unknown_c_before,
        "ROLA consumed unresolved carry input"
    );

    RamBus mc6801_bus;
    constexpr std::array<std::uint8_t, 1U> unstaged_program{0x49U};
    passed &= expect(
        mc6801_bus.load(0x1000U, unstaged_program),
        "MC6801 ROLA profile test load failed"
    );
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 ROLA execution was inherited"
    );
    return passed;
}

bool test_rolb() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::CpuRegister;
    using jr800::core::CpuStatePart;
    using jr800::core::Jr800Machine;
    using jr800::core::Jr800MemoryStatus;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    constexpr auto negative = condition_mask(ConditionCode::negative);
    constexpr auto zero = condition_mask(ConditionCode::zero);
    constexpr auto overflow = condition_mask(ConditionCode::overflow);
    constexpr auto carry = condition_mask(ConditionCode::carry);
    constexpr auto written = static_cast<std::uint8_t>(
        negative | zero | overflow | carry
    );
    constexpr auto preserved = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::half_carry)
        | condition_mask(ConditionCode::interrupt_mask)
    );

    RamBus exhaustive_bus;
    Cpu exhaustive_cpu;
    RecordingObserver observer;
    bool passed = expect(
        exhaustive_bus.set_observer(&observer),
        "ROLB observer attach failed"
    );
    bool exhaustive_match = true;
    for (std::uint16_t input = 0U;
         input <= 0x00FFU && exhaustive_match;
         ++input) {
        for (std::uint8_t carry_input = 0U;
             carry_input <= 1U && exhaustive_match;
             ++carry_input) {
            const auto operand = static_cast<std::uint8_t>(input);
            const std::array<std::uint8_t, 10U> program{
                0x86U, 0x30U,
                0x06U,
                0x86U, 0x5AU,
                0xC6U, operand,
                static_cast<std::uint8_t>(
                    carry_input != 0U ? 0x0DU : 0x0CU
                ),
                0x0BU,
                0x59U,
            };
            exhaustive_match = exhaustive_bus.load(0x1000U, program);
            exhaustive_cpu.initialize(
                CpuProfile::hd6301v1,
                0x1000U,
                0x01FFU
            );
            if (!exhaustive_match
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()
                || !exhaustive_cpu.step_instruction(exhaustive_bus).succeeded()) {
                exhaustive_match = false;
                break;
            }

            const auto before = exhaustive_cpu.state();
            observer.clear();
            const auto result = static_cast<std::uint8_t>(
                static_cast<std::uint8_t>(operand << 1U)
                | carry_input
            );
            const auto new_carry_set = (operand & 0x80U) != 0U;
            const auto negative_set = (result & 0x80U) != 0U;
            std::uint8_t expected_flags{};
            if (negative_set) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | negative
                );
            }
            if (result == 0U) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | zero
                );
            }
            if (negative_set != new_carry_set) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | overflow
                );
            }
            if (new_carry_set) {
                expected_flags = static_cast<std::uint8_t>(
                    expected_flags | carry
                );
            }
            auto expected = before;
            expected.b = result;
            expected.condition_code = static_cast<std::uint8_t>(
                (expected.condition_code & ~written) | expected_flags
            );
            expected.knowledge.condition_code = static_cast<std::uint8_t>(
                expected.knowledge.condition_code | written
            );
            expected.pc = 0x100AU;
            expected.cycle_count = 10U;

            const auto step = exhaustive_cpu.step_instruction(exhaustive_bus);
            exhaustive_match = before.a == 0x5AU && before.b == operand
                && (before.condition_code & preserved) == preserved
                && (before.condition_code & overflow) == overflow
                && ((before.condition_code & carry) != 0U)
                    == (carry_input != 0U)
                && step.succeeded() && step.bytes_fetched == 1U
                && step.instruction_length == 1U && step.cycles == 1U
                && step.pc_before == 0x1009U && step.pc_after == 0x100AU
                && step.bytes[0] == 0x59U
                && exhaustive_cpu.state() == expected
                && observer.count == 1U
                && observer.events[0].kind == AccessKind::instruction_fetch
                && observer.events[0].address == 0x1009U
                && observer.events[0].value == 0x59U;
        }
    }
    passed &= expect(
        exhaustive_match,
        "ROLB exhaustive result, carry input, flags, state, timing, or trace differs"
    );

    Jr800Machine partial_machine;
    auto partial_rom = nop_rom();
    partial_rom[0U] = 0xC6U;
    partial_rom[1U] = 0x00U;
    partial_rom[2U] = 0x0DU;
    partial_rom[3U] = 0x59U;
    partial_rom[partial_rom.size() - 2U] = 0x80U;
    partial_rom[partial_rom.size() - 1U] = 0x00U;
    passed &= expect(
        partial_machine.load_logical_rom(partial_rom) == Jr800MemoryStatus::ok
            && partial_machine.initialize_from_reset_entry().succeeded()
            && partial_machine.execution().step_instruction().succeeded()
            && partial_machine.execution().step_instruction().succeeded(),
        "ROLB partial-knownness setup failed"
    );
    const auto partial_before = partial_machine.execution().cpu().state();
    auto partial_expected = partial_before;
    partial_expected.b = 0x01U;
    partial_expected.condition_code = static_cast<std::uint8_t>(
        partial_expected.condition_code & ~written
    );
    partial_expected.knowledge.condition_code = static_cast<std::uint8_t>(
        partial_expected.knowledge.condition_code | written
    );
    partial_expected.pc = 0x8004U;
    partial_expected.cycle_count = 4U;
    const auto partial_step = partial_machine.execution().step_instruction();
    passed &= expect(
        !partial_before.knowledge.knows(CpuRegister::accumulator_a)
            && partial_before.knowledge.knows(CpuRegister::accumulator_b)
            && !partial_before.knowledge.knows(CpuRegister::index_register)
            && !partial_before.knowledge.knows(CpuRegister::stack_pointer)
            && (partial_before.knowledge.condition_code & carry) == carry
            && partial_step.succeeded() && partial_step.bytes_fetched == 1U
            && partial_step.cycles == 1U
            && partial_machine.execution().cpu().state() == partial_expected,
        "ROLB changed preserved reset-time state or knownness"
    );

    RamBus wrap_bus;
    RecordingObserver wrap_observer;
    passed &= expect(
        wrap_bus.set_observer(&wrap_observer),
        "ROLB wrap observer attach failed"
    );
    constexpr std::array<std::uint8_t, 4U> wrap_program{
        0xC6U, 0x80U, 0x0DU, 0x59U,
    };
    passed &= expect(
        wrap_bus.load(0xFFFCU, wrap_program),
        "ROLB wrap program load failed"
    );
    Cpu wrap_cpu;
    wrap_cpu.initialize(CpuProfile::hd6301v1, 0xFFFCU, 0x01FFU);
    passed &= expect(
        wrap_cpu.step_instruction(wrap_bus).succeeded()
            && wrap_cpu.step_instruction(wrap_bus).succeeded(),
        "ROLB wrap state seed failed"
    );
    wrap_observer.clear();
    const auto wrap_step = wrap_cpu.step_instruction(wrap_bus);
    passed &= expect(
        wrap_step.succeeded() && wrap_step.pc_before == 0xFFFFU
            && wrap_step.pc_after == 0x0000U && wrap_step.cycles == 1U
            && wrap_cpu.state().b == 0x01U
            && (wrap_cpu.state().condition_code & written)
                == static_cast<std::uint8_t>(overflow | carry)
            && wrap_observer.count == 1U
            && wrap_observer.events[0].kind == AccessKind::instruction_fetch
            && wrap_observer.events[0].address == 0xFFFFU
            && wrap_observer.events[0].value == 0x59U,
        "ROLB PC wrap, carry case, or architectural fetch differs"
    );

    Jr800Machine unknown_b_machine;
    auto unknown_b_rom = nop_rom();
    unknown_b_rom[0U] = 0x0CU;
    unknown_b_rom[1U] = 0x59U;
    unknown_b_rom[unknown_b_rom.size() - 2U] = 0x80U;
    unknown_b_rom[unknown_b_rom.size() - 1U] = 0x00U;
    passed &= expect(
        unknown_b_machine.load_logical_rom(unknown_b_rom)
                == Jr800MemoryStatus::ok
            && unknown_b_machine.initialize_from_reset_entry().succeeded()
            && unknown_b_machine.execution().step_instruction().succeeded(),
        "ROLB unknown-B setup failed"
    );
    const auto unknown_b_before = unknown_b_machine.execution().cpu().state();
    const auto unknown_b = unknown_b_machine.execution().step_instruction();
    passed &= expect(
        unknown_b.fault == CpuFault::unknown_state
            && unknown_b.state_fault == CpuStatePart::accumulator_b
            && unknown_b.bytes_fetched == 1U
            && unknown_b.instruction_length == 1U && unknown_b.cycles == 0U
            && unknown_b_machine.execution().cpu().state() == unknown_b_before,
        "ROLB did not prioritize unresolved accumulator B"
    );

    Jr800Machine unknown_c_machine;
    auto unknown_c_rom = nop_rom();
    unknown_c_rom[0U] = 0xC6U;
    unknown_c_rom[1U] = 0x01U;
    unknown_c_rom[2U] = 0x59U;
    unknown_c_rom[unknown_c_rom.size() - 2U] = 0x80U;
    unknown_c_rom[unknown_c_rom.size() - 1U] = 0x00U;
    passed &= expect(
        unknown_c_machine.load_logical_rom(unknown_c_rom)
                == Jr800MemoryStatus::ok
            && unknown_c_machine.initialize_from_reset_entry().succeeded()
            && unknown_c_machine.execution().step_instruction().succeeded(),
        "ROLB unknown-C setup failed"
    );
    const auto unknown_c_before = unknown_c_machine.execution().cpu().state();
    const auto unknown_c = unknown_c_machine.execution().step_instruction();
    passed &= expect(
        unknown_c.fault == CpuFault::unknown_state
            && unknown_c.state_fault == CpuStatePart::condition_code
            && unknown_c.bytes_fetched == 1U
            && unknown_c.instruction_length == 1U && unknown_c.cycles == 0U
            && unknown_c_machine.execution().cpu().state() == unknown_c_before,
        "ROLB consumed unresolved carry input"
    );

    RamBus mc6801_bus;
    mc6801_bus.poke8(0x1000U, 0x59U);
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 ROLB execution was inherited"
    );
    return passed;
}

