bool test_clv() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    bool passed = true;
    RamBus bus;
    RecordingObserver observer;
    passed &= expect(bus.set_observer(&observer), "CLV observer attach failed");
    constexpr std::array<std::uint8_t, 9U> program{
        0x86U, 0xFFU,
        0x8BU, 0x01U,
        0x86U, 0x7FU,
        0x4CU,
        0x0FU,
        0x0AU,
    };
    passed &= expect(bus.load(0x1000U, program), "CLV program load failed");

    Cpu cpu;
    cpu.initialize(CpuProfile::hd6301v1, 0x1000U, 0x01FFU);
    passed &= expect(
        cpu.step_instruction(bus).succeeded()
            && cpu.step_instruction(bus).succeeded()
            && cpu.step_instruction(bus).succeeded()
            && cpu.step_instruction(bus).succeeded()
            && cpu.step_instruction(bus).succeeded(),
        "CLV state seed failed"
    );
    const auto before = cpu.state();
    constexpr auto overflow = condition_mask(ConditionCode::overflow);
    constexpr auto zero = condition_mask(ConditionCode::zero);
    constexpr auto preserved_set = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::half_carry)
        | condition_mask(ConditionCode::interrupt_mask)
        | condition_mask(ConditionCode::negative)
        | condition_mask(ConditionCode::carry)
    );
    passed &= expect(
        (before.condition_code & overflow) == overflow
            && (before.condition_code & preserved_set) == preserved_set
            && (before.condition_code & zero) == 0U,
        "CLV flag preconditions differ"
    );
    auto expected = before;
    expected.pc = 0x1009U;
    expected.condition_code = static_cast<std::uint8_t>(
        expected.condition_code & ~overflow
    );
    expected.knowledge.condition_code = static_cast<std::uint8_t>(
        expected.knowledge.condition_code | overflow
    );
    expected.cycle_count += 1U;
    observer.clear();
    const auto step = cpu.step_instruction(bus);
    passed &= expect(
        step.succeeded() && step.bytes_fetched == 1U
            && step.instruction_length == 1U && step.cycles == 1U
            && cpu.state() == expected,
        "CLV state, flags, knownness, or timing differs"
    );
    passed &= expect(
        observer.count == 1U
            && observer.events[0].kind == AccessKind::instruction_fetch
            && observer.events[0].address == 0x1008U
            && observer.events[0].value == 0x0AU,
        "CLV architectural fetch order differs"
    );

    RamBus mc6801_bus;
    mc6801_bus.poke8(0x1000U, 0x0AU);
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 CLV execution was inherited"
    );
    return passed;
}

