bool test_clrb() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::CpuRegister;
    using jr800::core::Jr800Machine;
    using jr800::core::Jr800MemoryStatus;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    constexpr auto written = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::negative)
        | condition_mask(ConditionCode::zero)
        | condition_mask(ConditionCode::overflow)
        | condition_mask(ConditionCode::carry)
    );
    constexpr auto preserved = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::half_carry)
        | condition_mask(ConditionCode::interrupt_mask)
    );

    bool passed = true;
    RamBus bus;
    RecordingObserver observer;
    passed &= expect(bus.set_observer(&observer), "CLRB observer attach failed");
    constexpr std::array<std::uint8_t, 5U> program{
        0x0FU,
        0x0DU,
        0xC6U, 0x80U,
        0x5FU,
    };
    passed &= expect(bus.load(0x1000U, program), "CLRB program load failed");

    Cpu cpu;
    cpu.initialize(CpuProfile::hd6301v1, 0x1000U, 0x01FFU);
    passed &= expect(
        cpu.step_instruction(bus).succeeded()
            && cpu.step_instruction(bus).succeeded()
            && cpu.step_instruction(bus).succeeded(),
        "CLRB state seed failed"
    );
    const auto before = cpu.state();
    observer.clear();
    auto expected = before;
    expected.b = 0U;
    expected.pc = 0x1005U;
    expected.condition_code = static_cast<std::uint8_t>(
        (expected.condition_code & ~written)
        | condition_mask(ConditionCode::zero)
    );
    expected.knowledge.registers = static_cast<std::uint8_t>(
        expected.knowledge.registers
        | jr800::core::register_mask(CpuRegister::accumulator_b)
    );
    expected.knowledge.condition_code = static_cast<std::uint8_t>(
        expected.knowledge.condition_code | written
    );
    expected.cycle_count = 5U;

    const auto step = cpu.step_instruction(bus);
    passed &= expect(
        step.succeeded() && step.bytes_fetched == 1U
            && step.instruction_length == 1U && step.cycles == 1U
            && step.pc_before == 0x1004U && step.pc_after == 0x1005U
            && step.bytes[0] == 0x5FU && cpu.state() == expected
            && (cpu.state().condition_code & preserved)
                == (before.condition_code & preserved)
            && (cpu.state().knowledge.condition_code & preserved)
                == (before.knowledge.condition_code & preserved),
        "CLRB result, flags, knownness, or timing differs"
    );
    passed &= expect(
        observer.count == 1U
            && observer.events[0].kind == AccessKind::instruction_fetch
            && observer.events[0].address == 0x1004U
            && observer.events[0].value == 0x5FU,
        "CLRB architectural fetch order differs"
    );

    Jr800Machine reset_machine;
    auto reset_rom = nop_rom();
    reset_rom[0U] = 0x5FU;
    reset_rom[reset_rom.size() - 2U] = 0x80U;
    reset_rom[reset_rom.size() - 1U] = 0x00U;
    passed &= expect(
        reset_machine.load_logical_rom(reset_rom) == Jr800MemoryStatus::ok
            && reset_machine.initialize_from_reset_entry().succeeded(),
        "Reset-state CLRB setup failed"
    );
    const auto reset_before = reset_machine.execution().cpu().state();
    const auto reset_step = reset_machine.execution().step_instruction();
    const auto& reset_after = reset_machine.execution().cpu().state();
    passed &= expect(
        !reset_before.knowledge.knows(CpuRegister::accumulator_b)
            && reset_step.succeeded() && reset_step.cycles == 1U
            && reset_after.pc == 0x8001U && reset_after.b == 0U
            && reset_after.cycle_count == 1U
            && reset_after.knowledge.knows(CpuRegister::accumulator_b)
            && !reset_after.knowledge.knows(CpuRegister::accumulator_a)
            && !reset_after.knowledge.knows(CpuRegister::index_register)
            && !reset_after.knowledge.knows(CpuRegister::stack_pointer)
            && (reset_after.condition_code & written)
                == condition_mask(ConditionCode::zero)
            && reset_after.knowledge.condition_code
                == static_cast<std::uint8_t>(
                    reset_before.knowledge.condition_code | written
                )
            && (reset_after.condition_code & preserved)
                == (reset_before.condition_code & preserved),
        "CLRB did not establish reset-time unknown accumulator B"
    );

    RamBus mc6801_bus;
    mc6801_bus.poke8(0x1000U, 0x5FU);
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 CLRB execution was inherited"
    );
    return passed;
}

bool test_deca() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::CpuRegister;
    using jr800::core::CpuStatePart;
    using jr800::core::Jr800Machine;
    using jr800::core::Jr800MemoryStatus;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    struct Case {
        std::uint8_t operand;
        std::uint8_t result;
        std::uint8_t flags;
    };
    constexpr std::array cases{
        Case{0x02U, 0x01U, 0x00U},
        Case{0x01U, 0x00U, condition_mask(ConditionCode::zero)},
        Case{0x00U, 0xFFU, condition_mask(ConditionCode::negative)},
        Case{0x80U, 0x7FU, condition_mask(ConditionCode::overflow)},
    };
    constexpr auto written = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::negative)
        | condition_mask(ConditionCode::zero)
        | condition_mask(ConditionCode::overflow)
    );
    constexpr auto preserved = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::half_carry)
        | condition_mask(ConditionCode::interrupt_mask)
        | condition_mask(ConditionCode::carry)
    );

    bool passed = true;
    for (const auto& test_case : cases) {
        RamBus bus;
        RecordingObserver observer;
        passed &= expect(bus.set_observer(&observer), "DECA observer attach failed");
        const std::array<std::uint8_t, 4U> program{
            0x0FU,
            0x86U, test_case.operand,
            0x4AU,
        };
        passed &= expect(bus.load(0x1000U, program), "DECA program load failed");

        Cpu cpu;
        cpu.initialize(CpuProfile::hd6301v1, 0x1000U, 0x01FFU);
        passed &= expect(
            cpu.step_instruction(bus).succeeded()
                && cpu.step_instruction(bus).succeeded(),
            "DECA state seed failed"
        );
        const auto condition_before = cpu.state().condition_code;
        observer.clear();

        const auto step = cpu.step_instruction(bus);
        passed &= expect(
            step.succeeded() && step.bytes_fetched == 1U
                && step.instruction_length == 1U && step.cycles == 1U
                && step.pc_before == 0x1003U && step.pc_after == 0x1004U
                && cpu.state().a == test_case.result
                && cpu.state().knowledge.knows(CpuRegister::accumulator_a)
                && cpu.state().cycle_count == 4U
                && (cpu.state().condition_code & written) == test_case.flags
                && (cpu.state().condition_code & preserved)
                    == (condition_before & preserved),
            "DECA result, flags, knownness, or timing differs"
        );
        passed &= expect(
            observer.count == 1U
                && observer.events[0].kind == AccessKind::instruction_fetch
                && observer.events[0].address == 0x1003U
                && observer.events[0].value == 0x4AU,
            "DECA architectural fetch order differs"
        );
    }

    RamBus mc6801_bus;
    mc6801_bus.poke8(0x1000U, 0x4AU);
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 DECA execution was inherited"
    );

    Jr800Machine reset_machine;
    auto reset_rom = nop_rom();
    reset_rom[0U] = 0x4AU;
    reset_rom[reset_rom.size() - 2U] = 0x80U;
    reset_rom[reset_rom.size() - 1U] = 0x00U;
    passed &= expect(
        reset_machine.load_logical_rom(reset_rom) == Jr800MemoryStatus::ok
            && reset_machine.initialize_from_reset_entry().succeeded(),
        "Unknown-state DECA setup failed"
    );
    const auto reset_before = reset_machine.execution().cpu().state();
    const auto unknown = reset_machine.execution().step_instruction();
    passed &= expect(
        unknown.fault == CpuFault::unknown_state
            && unknown.state_fault == CpuStatePart::accumulator_a
            && unknown.bytes_fetched == 1U
            && reset_machine.execution().cpu().state() == reset_before,
        "DECA consumed unresolved reset-time accumulator A"
    );
    return passed;
}

