bool test_ldaa_extended() {
    using jr800::core::AccessKind;
    using jr800::core::ConditionCode;
    using jr800::core::Cpu;
    using jr800::core::CpuFault;
    using jr800::core::CpuRegister;
    using jr800::core::Jr800Machine;
    using jr800::core::Jr800MemoryStatus;
    using jr800::core::RamBus;
    using jr800::core::condition_mask;
    using jr800::isa::CpuProfile;

    struct Case {
        std::uint8_t value;
        std::uint8_t flags;
    };
    constexpr std::array cases{
        Case{0x2AU, 0x00U},
        Case{0x00U, condition_mask(ConditionCode::zero)},
        Case{0x80U, condition_mask(ConditionCode::negative)},
    };
    constexpr auto written = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::negative)
        | condition_mask(ConditionCode::zero)
        | condition_mask(ConditionCode::overflow)
    );
    constexpr auto preserved = static_cast<std::uint8_t>(
        condition_mask(ConditionCode::half_carry)
        | condition_mask(ConditionCode::interrupt_mask)
        | condition_mask(ConditionCode::carry)
    );

    bool passed = true;
    for (const auto& test_case : cases) {
        RamBus bus;
        RecordingObserver observer;
        passed &= expect(
            bus.set_observer(&observer),
            "Extended LDAA observer attach failed"
        );
        constexpr std::array<std::uint8_t, 4U> program{
            0x0FU,
            0xB6U, 0x23U, 0x45U,
        };
        passed &= expect(
            bus.load(0x1000U, program),
            "Extended LDAA program load failed"
        );
        bus.poke8(0x2345U, test_case.value);

        Cpu cpu;
        cpu.initialize(CpuProfile::hd6301v1, 0x1000U, 0x01FFU);
        passed &= expect(
            cpu.step_instruction(bus).succeeded(),
            "Extended LDAA flag seed failed"
        );
        const auto before = cpu.state();
        observer.clear();

        const auto step = cpu.step_instruction(bus);
        passed &= expect(
            step.succeeded() && step.bytes_fetched == 3U
                && step.instruction_length == 3U && step.cycles == 4U
                && step.pc_before == 0x1001U && step.pc_after == 0x1004U
                && step.bytes[0] == 0xB6U && step.bytes[1] == 0x23U
                && step.bytes[2] == 0x45U
                && cpu.state().a == test_case.value
                && cpu.state().knowledge.knows(CpuRegister::accumulator_a)
                && cpu.state().cycle_count == 5U
                && (cpu.state().condition_code & written) == test_case.flags
                && (cpu.state().condition_code & preserved)
                    == (before.condition_code & preserved)
                && (cpu.state().knowledge.condition_code & written) == written
                && (cpu.state().knowledge.condition_code & preserved)
                    == (before.knowledge.condition_code & preserved),
            "Extended LDAA result, flags, knownness, or timing differs"
        );
        passed &= expect(
            observer.count == 4U
                && observer.events[0].kind == AccessKind::instruction_fetch
                && observer.events[0].address == 0x1001U
                && observer.events[0].value == 0xB6U
                && observer.events[1].kind == AccessKind::instruction_fetch
                && observer.events[1].address == 0x1002U
                && observer.events[1].value == 0x23U
                && observer.events[2].kind == AccessKind::instruction_fetch
                && observer.events[2].address == 0x1003U
                && observer.events[2].value == 0x45U
                && observer.events[3].kind == AccessKind::data_read
                && observer.events[3].address == 0x2345U
                && observer.events[3].value == test_case.value,
            "Extended LDAA architectural access order differs"
        );
    }

    Jr800Machine reset_machine;
    auto reset_rom = nop_rom();
    reset_rom[0U] = 0xB6U;
    reset_rom[1U] = 0x80U;
    reset_rom[2U] = 0x04U;
    reset_rom[4U] = 0x80U;
    reset_rom[reset_rom.size() - 2U] = 0x80U;
    reset_rom[reset_rom.size() - 1U] = 0x00U;
    passed &= expect(
        reset_machine.load_logical_rom(reset_rom) == Jr800MemoryStatus::ok
            && reset_machine.initialize_from_reset_entry().succeeded(),
        "Reset-state extended LDAA setup failed"
    );
    const auto reset_before = reset_machine.execution().cpu().state();
    const auto reset_step = reset_machine.execution().step_instruction();
    const auto& reset_after = reset_machine.execution().cpu().state();
    const auto reset_written_condition = static_cast<std::uint8_t>(
        reset_before.knowledge.condition_code | written
    );
    passed &= expect(
        !reset_before.knowledge.knows(CpuRegister::accumulator_a)
            && reset_step.succeeded() && reset_step.cycles == 4U
            && reset_after.pc == 0x8003U && reset_after.a == 0x80U
            && reset_after.cycle_count == 4U
            && reset_after.knowledge.knows(CpuRegister::accumulator_a)
            && (reset_after.condition_code & written)
                == condition_mask(ConditionCode::negative)
            && reset_after.knowledge.condition_code
                == reset_written_condition,
        "Extended LDAA did not establish reset-time unknown accumulator state"
    );

    RamBus mc6801_bus;
    constexpr std::array<std::uint8_t, 3U> unstaged_program{
        0xB6U, 0x23U, 0x45U,
    };
    passed &= expect(
        mc6801_bus.load(0x1000U, unstaged_program),
        "MC6801 extended LDAA profile test load failed"
    );
    mc6801_bus.poke8(0x2345U, 0x5AU);
    Cpu mc6801;
    mc6801.initialize(CpuProfile::mc6801, 0x1000U, 0x01FFU);
    const auto mc6801_before = mc6801.state();
    const auto unstaged = mc6801.step_instruction(mc6801_bus);
    passed &= expect(
        unstaged.fault == CpuFault::unsupported_opcode
            && unstaged.bytes_fetched == 1U
            && mc6801.state() == mc6801_before,
        "Unreviewed MC6801 extended LDAA execution was inherited"
    );
    return passed;
}

